insert into public.evidence_sources(source_key,source_url,source_type,evidence_grade,notes) values('chuo-main-plan-20261017-PLAN:CHUO-REGIONAL','https://www.jreast.co.jp/press/2026/nagano/20260507_na01.pdf','reference','C','Published regional Nagano fleet transition plan. Replaces legacy unqualified 211/E233 mixed candidates only when a regional source model is present. E233 green-car through services remain separate. Not an observed daily carset; E131 model announcement is a fleet plan, not proof of an individual assignment.') on conflict(source_key) do nothing;
